// seed: tests/seed.reg1.spec.ts
// Расхождения плана с живым приложением (19.11.2026):
//  - строк не 15, а 16: между «יתרות ורכישות» и «המתנות שקיבלתי» есть ещё «מתנות ורצף» (→ /streak, заголовок «רצף כניסות») — проверяется тоже;
//  - в подписях разделитель «·», а не «•» («עד 100 ק״מ · 18–60+»); принимаем оба;
//  - «יתרות ורכישות» и «Magnet Premium» ведут на один и тот же экран /subscription («המנוי שלי»);
//  - «стрелка назад» на разных экранах называется по-разному: «סגירה» (большинство), «ביטול» (עריכת פרופיל), «חזרה» (השלמת שאלות פרופיל); на экране «אימות פנים» (/verification) у верифицированного пользователя шапки нет, есть только «חזרה לפרופיל» (ведёт в профиль) — возвращаемся через page.goBack();
//  - у «עריכת פרופיל» заголовок — имя пользователя и вкладки «עריכה»/«תצוגה»; у «השלמת שאלות פרופיל» — «השלמת פרופיל»; у «השידוך שלי» — «שדכנית אישית»;
//  - у «העדפות חיפוש» кнопки «שמירה» нет;
//  - «העדפות חיפוש» открывается как /prefs?from=settings.
// Тумблеры, «מחיקת חשבון», «התנתקות», блокировки не трогаются; на экранах только открыть и вернуться.
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/reg1-r12.json'),
  colorScheme: 'dark',
});

type Screen = { row: string; url: RegExp; marker: string | RegExp; back: string | null };

const SCREENS: Screen[] = [
  { row: 'עריכת פרופיל', url: /\/edit-profile/, marker: 'עריכה', back: 'ביטול' },
  { row: 'השלמת שאלות פרופיל', url: /\/profile-questions/, marker: 'השלמת פרופיל', back: 'חזרה' },
  { row: 'אימות פנים', url: /\/verification/, marker: 'את/ה מאומת/ת!', back: null },
  { row: 'שיטות כניסה', url: /\/sign-in-methods/, marker: 'שיטות כניסה', back: 'סגירה' },
  { row: 'העדפות חיפוש', url: /\/prefs/, marker: 'העדפות חיפוש', back: 'סגירה' },
  { row: 'התראות', url: /\/notification-settings/, marker: 'התראות', back: 'סגירה' },
  { row: 'מצב שקט לדייט', url: /\/quiet-mode/, marker: 'מצב שקט לדייט', back: 'סגירה' },
  { row: 'Magnet Premium', url: /\/subscription/, marker: 'המנוי שלי', back: 'סגירה' },
  { row: 'יתרות ורכישות', url: /\/subscription/, marker: 'המנוי שלי', back: 'סגירה' },
  { row: 'מתנות ורצף', url: /\/streak/, marker: 'רצף כניסות', back: 'סגירה' },
  { row: 'המתנות שקיבלתי', url: /\/gifts/, marker: 'המתנות שקיבלתי', back: 'סגירה' },
  { row: 'המתנות ששלחתי', url: /\/gift\/history/, marker: 'המתנות ששלחתי', back: 'סגירה' },
  { row: 'השידוך שלי', url: /\/matchmaker/, marker: 'שדכנית אישית', back: 'סגירה' },
  { row: 'פרטיות ומחיקת חשבון', url: /\/privacy/, marker: 'פרטיות ומחיקת חשבון', back: 'סגירה' },
  { row: 'משתמשים חסומים', url: /\/blocked-users/, marker: 'משתמשים חסומים', back: 'סגירה' },
  { row: 'תנאי שימוש ומדיניות פרטיות', url: /\/terms/, marker: 'תנאי שימוש ומדיניות פרטיות', back: 'סגירה' },
];

test.describe('הגדרות (#e5e14a)', () => {
  test('Группы, строки, переходы на экраны и возврат @iphone @prod-safe', async ({ page }) => {
    // 1. /settings — группы и строки (до «התנתקות»)
    await page.goto('/settings');
    await expect(page.getByText('הגדרות', { exact: true }).first()).toBeVisible();

    for (const group of ['חשבון', 'גילוי', 'מנוי ורכישות', 'פרטיות ואבטחה']) {
      await expect(page.getByText(group, { exact: true }).filter({ visible: true }).first()).toBeVisible();
    }
    const rowOf = (name: string) => page.getByRole('button', { name, exact: true });

    await expect(rowOf('השלמת שאלות פרופיל')).toContainText(/\d+%/);
    await expect(rowOf('אימות פנים')).toContainText('מאומת/ת');
    await expect(rowOf('העדפות חיפוש')).toContainText(/עד \d+ ק״מ\s*[·•]\s*/);
    await expect(page.getByRole('switch', { name: 'מיקום', exact: true })).toBeVisible();
    await expect(page.getByText('מוצג/ת על המפה ובחיפוש לפי מרחק')).toBeVisible();
    await expect(page.getByRole('switch', { name: 'היו כאן', exact: true })).toBeVisible();
    await expect(rowOf('מצב שקט לדייט').getByText('כבוי', { exact: true })).toBeVisible();

    const appLock = page.getByRole('switch', { name: 'נעילת אפליקציה' });
    await appLock.scrollIntoViewIfNeeded();
    await expect(page.getByText('זמין באפליקציה בלבד')).toBeVisible();
    await expect(appLock).toBeDisabled();

    const logout = rowOf('התנתקות');
    await logout.scrollIntoViewIfNeeded();
    await expect(logout).toBeVisible();

    // 2–3. Строки по очереди: экран открывается, «назад» возвращает в «הגדרות»
    for (const s of SCREENS) {
      await test.step(`Строка «${s.row}»`, async () => {
        const row = rowOf(s.row);
        await row.scrollIntoViewIfNeeded();
        await row.click();
        await expect(page).toHaveURL(s.url);
        await expect(page.getByText(s.marker, { exact: true }).filter({ visible: true }).first()).toBeVisible();

        if (s.row === 'פרטיות ומחיקת חשבון') {
          for (const block of ['נראות', 'חסימות', 'מסמכים', 'חשבון']) {
            await expect(page.getByText(block, { exact: true }).filter({ visible: true }).first()).toBeVisible();
          }
          await expect(page.getByRole('button', { name: 'מחיקת חשבון' }).filter({ visible: true })).toBeVisible();
        }
        if (s.row === 'העדפות חיפוש') {
          await expect(page.getByRole('button', { name: 'שמירה' })).toBeHidden();
        }

        if (s.back) {
          await page.getByRole('button', { name: s.back, exact: true }).filter({ visible: true }).last().click();
        } else {
          await page.goBack();
        }
        await expect(page).toHaveURL(/\/settings/);
        await expect(page.getByText('הגדרות', { exact: true }).filter({ visible: true }).first()).toBeVisible();
      });
    }
  });
});
